draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw body
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // draw arms and legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 30);
  ctx.lineTo(W/2 - 40, H/2 - 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 30);
  ctx.lineTo(W/2 + 40, H/2 - 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 40, H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 40, H/2 + 60);
  ctx.stroke();

  // draw inflamed area
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 + 20 + 10 * Math.sin(t), H/2 + 20 + 10 * Math.cos(t), 10, 0, 2 * Math.PI);
  ctx.fill();

  // draw junk food
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.rect(W/2 - 50 + 20 * Math.sin(t), H/2 - 80, 20, 10);
  ctx.fill();

  // draw healthy food
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.rect(W/2 + 30 + 20 * Math.cos(t), H/2 - 80, 20, 10);
  ctx.fill();

  ctx.restore();
}
